def test_order_prices_catalog_money_objects():
    catalog = sample_catalog()
    assert price_order([{"sku": "PEN", "quantity": 2}, {"sku": "PAD", "quantity": 1}], catalog) == {
        "total_cents": 550,
        "currency": "USD",
    }


